375	    /**
376	     * Rejects an owner payload that is missing or blank in any mandatory field. This complements Bean
377	     * Validation, which cannot reject whitespace-only values that still satisfy a minimum-length constraint.
378	     *
379	     * @param fields the submitted owner fields
380	     * @throws RequiredFieldsMissingException if any of firstName, lastName, city or telephone is
381	     *                                        {@code null} or blank, or if the owner supplies no address
382	     *                                        in either form (a blank structured {@code addressLine1} and a
383	     *                                        blank flat {@code address}, each measured after normalization)
384	     */
385	    /**
386	     * Reads the client-supplied {@code Idempotency-Key} header for the current create request, if any.
387	     *
388	     * @return the trimmed idempotency key, or {@code null} when the header is absent or blank
389	     */
390	    private String idempotencyKey() {
391	        String key = this.request.getHeader(IDEMPOTENCY_KEY_HEADER);
392	        if (key == null || key.isBlank()) {
393	            return null;
394	        }
395	        return key.strip();
396	    }
397	
398	    private void rejectMissingOrBlankFields(OwnerFieldsDto fields) {
399	        List<String> missing = new ArrayList<>();
400	        if (isBlank(fields.getFirstName())) {
401	            missing.add("firstName");
402	        }
403	        if (isBlank(fields.getLastName())) {
404	            missing.add("lastName");
405	        }
406	        boolean hasStructuredAddress = !isBlank(normalizeAddress(fields.getAddressLine1()));
407	        boolean hasFlatAddress = !isBlank(normalizeAddress(fields.getAddress()));
408	        if (!hasStructuredAddress && !hasFlatAddress) {
409	            missing.add("address");
410	        }
411	        if (isBlank(fields.getCity())) {
412	            missing.add("city");
413	        }
414	        if (isBlank(fields.getTelephone())) {
415	            missing.add("telephone");
416	        }
417	        if (!missing.isEmpty()) {
418	            throw new RequiredFieldsMissingException(missing);
419	        }
420	    }
421	
422	    private boolean isBlank(String value) {
423	        return value == null || value.isBlank();
424	    }
