426	    /**
427	     * Inclusive 4-digit postcode ranges permitted per city region, keyed by the region derived from the
428	     * city via {@link OwnerLocality}: NSW 2000-2099, VIC 3000-3099, QLD 4000-4099. A region absent from
429	     * this table (i.e. {@code "UNKNOWN"}) imposes no range constraint, so any 4-digit postcode is accepted.
430	     */
431	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
432	        "NSW", new int[] {2000, 2099},
433	        "VIC", new int[] {3000, 3099},
434	        "QLD", new int[] {4000, 4099});
435	
436	    /**
437	     * Validates an owner's {@code postcode} when present. Postcode is optional: a {@code null} value is
438	     * accepted and left absent, keeping the create contract backward-compatible. When supplied it must be
439	     * a 4-digit value, and it must fall within the inclusive range for the city's region (NSW 2000-2099,
440	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
441	     *
442	     * @param postcode the submitted postcode, or {@code null} when omitted
443	     * @param city the owner's city, used to derive the region whose range constrains the postcode
444	     * @throws InvalidPostcodeException if a supplied postcode is not 4 digits or is out of range for the
445	     *                                  city's region
446	     */
447	    private void validatePostcode(String postcode, String city) {
448	        if (postcode == null) {
449	            return;
450	        }
451	        if (!postcode.matches("[0-9]{4}")) {
452	            throw new InvalidPostcodeException(postcode);
453	        }
454	        int[] range = REGION_POSTCODE_RANGE.get(OwnerLocality.of(city));
455	        if (range == null) {
456	            return;
457	        }
458	        int value = Integer.parseInt(postcode);
459	        if (value < range[0] || value > range[1]) {
460	            throw new InvalidPostcodeException(postcode);
461	        }
462	    }
463	
464	    /**
465	     * Normalizes a submitted telephone number into E.164 form, which becomes the stored and returned
466	     * value. Spaces, dashes and brackets are stripped. A leading {@code '+'} and its country code are
467	     * kept as supplied; otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
468	     * is dropped from the national digits. The result must be a {@code '+'} followed by 8 to 15 digits.
469	     * <p>
470	     * Where a per-country rule is defined the national-number length is validated against the country
471	     * code: {@code '+61'} (Australia) requires exactly 9 national digits and {@code '+1'} (NANP)
472	     * requires exactly 10.
473	     *
474	     * @param telephone the raw telephone value from the request
475	     * @return the E.164 telephone (a {@code '+'} followed by 8 to 15 digits)
476	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
477	     */
478	    private String normalizeTelephone(String telephone) {
479	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s()\\-]", "");
480	        String digits;
481	        if (cleaned.startsWith("+")) {
482	            digits = cleaned.substring(1);
483	        } else {
484	            // No country code supplied: assume Australia (+61) and drop a single leading '0'.
485	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
486	            digits = "61" + national;
487	        }
488	        if (!digits.matches("[0-9]{8,15}")) {
489	            throw new InvalidTelephoneException(cleaned);
490	        }
491	        // Validate the national-number length against the country code where a rule is defined.
492	        if (digits.startsWith("61") && digits.length() - 2 != 9) {
493	            throw new InvalidTelephoneException(cleaned);
494	        }
495	        if (digits.startsWith("1") && digits.length() - 1 != 10) {
496	            throw new InvalidTelephoneException(cleaned);
497	        }
498	        return "+" + digits;
499	    }
