527	     * Applies the owner's address in whichever form the request supplied, preferring the structured
528	     * fields. When a non-blank {@code addressLine1} is present, {@code addressLine1} and (when present)
529	     * {@code addressLine2} are normalized in place and the flat {@code address} is set to the composed
530	     * value: the normalized {@code addressLine1}, with a single space and the normalized
531	     * {@code addressLine2} appended when an {@code addressLine2} is present. Otherwise the structured
532	     * lines are cleared and the flat {@code address} is normalized on its own, keeping the earlier
533	     * flat-address contract backward-compatible.
534	     *
535	     * @param owner the owner being created, mapped straight from the request
536	     */
537	    private void applyAddress(Owner owner) {
538	        if (!isBlank(owner.getAddressLine1())) {
539	            String line1 = normalizeAddress(owner.getAddressLine1());
540	            owner.setAddressLine1(line1);
