557	    /**
558	     * Normalizes a submitted address into the form that is stored and returned. Leading and trailing
559	     * whitespace is removed, internal runs of whitespace are collapsed to a single space, the value is
560	     * upper-cased, and common street-type abbreviations are expanded ({@code ST -> STREET},
561	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). Abbreviations are only expanded when they form a whole
562	     * word, so an address such as {@code '  12  main  st '} normalizes to {@code '12 MAIN STREET'}.
563	     *
564	     * @param address the raw address value from the request (may be {@code null})
565	     * @return the normalized address, or an empty string when {@code address} is {@code null} or blank
566	     */
567	    private String normalizeAddress(String address) {
568	        if (address == null) {
569	            return "";
570	        }
571	        String collapsed = address.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
572	        if (collapsed.isEmpty()) {
573	            return "";
574	        }
575	        String[] tokens = collapsed.split(" ");
576	        StringBuilder sb = new StringBuilder(collapsed.length());
577	        for (int i = 0; i < tokens.length; i++) {
578	            if (i > 0) {
579	                sb.append(' ');
580	            }
581	            sb.append(expandAddressAbbreviation(tokens[i]));
582	        }
583	        return sb.toString();
584	    }
