586	    /**
587	     * Expands a single upper-cased address token from its common abbreviation to its full form, or
588	     * returns the token unchanged when it is not a recognised abbreviation.
589	     *
590	     * @param token an upper-cased whole-word address token
591	     * @return the expanded form ({@code STREET}, {@code ROAD}, {@code AVENUE}) or the original token
592	     */
593	    private String expandAddressAbbreviation(String token) {
594	        return switch (token) {
595	            case "ST" -> "STREET";
596	            case "RD" -> "ROAD";
597	            case "AVE" -> "AVENUE";
598	            default -> token;
599	        };
600	    }
