602	    /**
603	     * Builds the unified member id assigned to a newly created owner, formatted
604	     * {@code '<REGION><FY><HASH8><CHK>'} where {@code REGION} is the region derived from the owner's
605	     * postcode (falling back to the city when the postcode resolves to no known region), the same
606	     * derivation that yields the owner's locality; {@code FY} is the two-digit fiscal year of the owner's
607	     * (business-day-adjusted) {@code registrationDate}; {@code HASH8} is the first 8 upper-cased hex
608	     * characters of the SHA-256 digest of the owner's normalized telephone concatenated with the owner's
609	     * last name; and {@code CHK} is a single Luhn check digit computed over the digits of
610	     * {@code '<REGION><FY><HASH8>'} (e.g. {@code 'NSW261A2B3C4D7'}).
611	     * <p>
612	     * Should the computed id collide with an existing owner's {@code memberId}, it is de-duplicated by
613	     * appending {@code '-<n>'} with the smallest {@code n} of 2 or more that yields a value not already
614	     * held by any existing owner; the de-duplicated id is returned.
615	     *
616	     * @param owner the owner being created, with normalized telephone, postcode and registration date set
617	     * @return the assigned, collision-free member id
618	     */
619	    private String generateMemberId(Owner owner) {
620	        String region = OwnerLocality.of(owner.getCity(), owner.getPostcode());
621	        String fiscalYear = fiscalYearSuffix(owner.getRegistrationDate());
622	        String hash8 = sha256Hex(owner.getTelephone() + owner.getLastName())
623	            .substring(0, 8).toUpperCase(Locale.ROOT);
624	        String core = region + fiscalYear + hash8;
625	        String base = core + luhnCheckDigit(core);
626	        Set<String> existing = this.clinicService.findAllOwners().stream()
627	            .map(Owner::getMemberId)
628	            .filter(id -> id != null)
629	            .collect(java.util.stream.Collectors.toSet());
630	        if (!existing.contains(base)) {
631	            return base;
632	        }
633	        int n = 2;
634	        while (existing.contains(base + "-" + n)) {
635	            n++;
636	        }
637	        return base + "-" + n;
638	    }
