640	    /**
641	     * Returns the two-digit fiscal-year suffix ({@code '<YY>'}) for the given date: the last two digits of
642	     * the calendar year in which that date's fiscal year (starting 1 July) begins. This is the same value
643	     * carried by the DTO's {@code fiscalYear} and embedded as the {@code FY} segment of the member id.
644	     *
645	     * @param date the (business-day-adjusted) registration date
646	     * @return the zero-padded two-digit fiscal-year suffix
647	     */
648	    private String fiscalYearSuffix(LocalDate date) {
649	        int year = date.getYear();
650	        int start = date.getMonthValue() >= 7 ? year : year - 1;
651	        return String.format("%02d", start % 100);
652	    }
