654	    /**
655	     * Computes a single Luhn check digit (0-9) over the digits contained in {@code value}. Non-digit
656	     * characters are skipped; the rightmost digit is doubled and every second digit thereafter, digits
657	     * exceeding 9 after doubling have 9 subtracted, and the check digit is {@code (10 - sum % 10) % 10}.
658	     *
659	     * @param value the value whose contained digits are summed
660	     * @return the Luhn check digit (between 0 and 9 inclusive)
661	     */
662	    private int luhnCheckDigit(String value) {
663	        int sum = 0;
664	        boolean dbl = true;
665	        for (int i = value.length() - 1; i >= 0; i--) {
666	            char c = value.charAt(i);
667	            if (c < '0' || c > '9') {
668	                continue;
669	            }
670	            int d = c - '0';
671	            if (dbl) {
672	                d *= 2;
673	                if (d > 9) {
674	                    d -= 9;
675	                }
676	            }
677	            sum += d;
678	            dbl = !dbl;
679	        }
680	        return (10 - (sum % 10)) % 10;
681	    }
