683	    /**
684	     * Computes the full lower-case hex SHA-256 digest of the UTF-8 bytes of the given value.
685	     *
686	     * @param value the value to hash
687	     * @return the 64-character lower-case hex SHA-256 digest
688	     */
689	    private String sha256Hex(String value) {
690	        try {
691	            byte[] digest = MessageDigest.getInstance("SHA-256")
692	                .digest(value.getBytes(StandardCharsets.UTF_8));
693	            StringBuilder sb = new StringBuilder(digest.length * 2);
694	            for (byte b : digest) {
695	                sb.append(String.format("%02x", b));
696	            }
697	            return sb.toString();
698	        } catch (NoSuchAlgorithmException e) {
699	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
700	        }
701	    }
