736	    /**
737	     * Computes the membership level assigned to a newly created owner, applying the household level ceiling.
738	     * The owner's own (uncapped) level cannot exceed one above the current maximum membership level among
739	     * their existing household members, where every level is measured against the household's current size
740	     * (the owner's just-computed {@code householdSize}). When the owner has no existing household member the
741	     * ceiling does not apply and the uncapped level is returned. The count is taken before the new owner is
742	     * persisted, so it excludes the owner being created; the existing members share the deterministic
743	     * {@code householdId} and any soft-deleted owner is ignored.
744	     *
745	     * @param owner the owner being created, with its {@code householdId} and {@code householdSize} already set
746	     * @return the owner's membership level, capped at one above the existing household maximum
747	     */
748	    private Integer computeMembershipLevel(Owner owner) {
749	        Integer householdSize = owner.getHouseholdSize();
750	        Integer ownLevel = this.ownerMapper.membershipLevelForHouseholdSize(owner, householdSize);
751	        String householdId = owner.getHouseholdId();
752	        int maxExisting = this.clinicService.findAllOwners().stream()
753	            .filter(existing -> !isDeleted(existing))
754	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
755	            .mapToInt(existing -> this.ownerMapper.membershipLevelForHouseholdSize(existing, householdSize))
756	            .max()
757	            .orElse(-1);
758	        if (maxExisting < 0) {
759	            return ownLevel;
760	        }
761	        return Math.min(ownLevel, maxExisting + 1);
762	    }
