946	     * @param owner the owner being created, with normalized telephone and validated postcode already set
947	     * @param sharesHousehold whether the create declared the owner a household member
948	     */
949	    private void assignPossibleDuplicate(Owner owner, boolean sharesHousehold) {
950	        Integer matchId = null;
951	        if (!sharesHousehold && owner.getPostcode() != null) {
952	            String key = identityKey(owner);
953	            String soundex = soundex(owner.getLastName());
954	            matchId = this.clinicService.findAllOwners().stream()
955	                .filter(existing -> !isDeleted(existing))
956	                .filter(existing -> soundex.equals(soundex(existing.getLastName()))
957	                    && owner.getPostcode().equals(existing.getPostcode())
958	                    && !key.equals(identityKey(existing)))
959	                .map(Owner::getId)
960	                .filter(id -> id != null)
961	                .min(Comparator.naturalOrder())
962	                .orElse(null);
963	        }
964	        owner.setPossibleDuplicate(matchId != null);
965	        owner.setPossibleDuplicateOf(matchId);
966	    }
