982	     * soundex} of the last name, joined by {@code '|'} in that order before hashing (e.g. the digest of
983	     * {@code '+61412345678||F650'}). Telephone and email are stored already normalized, so the stored
984	     * values are used directly. This single 64-hex key is what duplicate detection compares.
985	     *
986	     * @param owner the owner whose identity key is being derived
987	     * @return the owner's identity key, a 64-character lower-case hex SHA-256 digest
988	     */
989	    private String identityKey(Owner owner) {
990	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
991	        String email = owner.getEmail() == null ? "" : owner.getEmail();
992	        String soundex = soundex(owner.getLastName());
993	        return sha256Hex(telephone + "|" + email + "|" + soundex);
994	    }
995	
996	    /**
997	     * Computes the American Soundex code of the given value: the retained (upper-cased) first letter
998	     * followed by three digits derived from the remaining consonants, right-padded with zeros or
999	     * truncated to length four. Non-letters are ignored; adjacent letters mapping to the same digit are
1000	     * coded once (bridged across {@code 'H'}/{@code 'W'}), and vowels reset the run so a repeated code
1001	     * separated by a vowel is coded twice. A {@code null} or letter-free value yields an empty string.
1002	     *
1003	     * @param value the value (typically a last name) to encode
1004	     * @return the four-character Soundex code, or an empty string when there are no letters
1005	     */
1006	    private String soundex(String value) {
1007	        if (value == null) {
1008	            return "";
1009	        }
1010	        String letters = value.toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
1011	        if (letters.isEmpty()) {
1012	            return "";
1013	        }
1014	        StringBuilder code = new StringBuilder().append(letters.charAt(0));
1015	        char prev = soundexDigit(letters.charAt(0));
1016	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
1017	            char c = letters.charAt(i);
1018	            if (c == 'H' || c == 'W') {
1019	                continue;
1020	            }
1021	            char digit = soundexDigit(c);
1022	            if (digit != '0' && digit != prev) {
1023	                code.append(digit);
1024	            }
1025	            prev = digit;
1026	        }
1027	        while (code.length() < 4) {
1028	            code.append('0');
1029	        }
1030	        return code.toString();
1031	    }
1032	
1033	    /**
1034	     * Maps a single upper-case letter to its Soundex digit ({@code '1'}-{@code '6'}), or {@code '0'} for
1035	     * vowels and the non-coding letters {@code H}/{@code W}/{@code Y}.
1036	     *
1037	     * @param c an upper-case letter
1038	     * @return the letter's Soundex digit
1039	     */
1040	    private char soundexDigit(char c) {
1041	        return switch (c) {
1042	            case 'B', 'F', 'P', 'V' -> '1';
1043	            case 'C', 'G', 'J', 'K', 'Q', 'S', 'X', 'Z' -> '2';
1044	            case 'D', 'T' -> '3';
1045	            case 'L' -> '4';
1046	            case 'M', 'N' -> '5';
1047	            case 'R' -> '6';
1048	            default -> '0';
1049	        };
1050	    }
1051	
1052	    /**
1053	     * Computes the owner's deterministic {@code householdId}: the first 12 hex characters of the SHA-256
1054	     * digest of {@code '<normalizedLastName>|<postcode>'}, where the last name is normalized with
1055	     * {@link #normalizeForComparison} and an absent postcode contributes an empty string. Because the
1056	     * identifier is a pure function of last name and postcode, any two owners sharing those values share
1057	     * the household automatically, with no cross-owner mutation. The value is assigned to every owner,
1058	     * whether or not {@code sharesHousehold} was requested.
1059	     *
1060	     * @param owner the owner being created, with its validated postcode already set
1061	     * @return the deterministic household identifier
1062	     */
1063	    private String computeHouseholdId(Owner owner) {
1064	        String normalizedLastName = normalizeForComparison(owner.getLastName());
1065	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
1066	        return sha256Hex(normalizedLastName + "|" + postcode).substring(0, 12);
1067	    }
1068	
1069	    /**
1070	     * Normalizes a value for household-identity comparison: leading and trailing whitespace is
1071	     * removed, internal runs of whitespace are collapsed to a single space, and the result is
1072	     * lower-cased.
1073	     *
1074	     * @param value the raw value to normalize (may be {@code null})
1075	     * @return the normalized value, or an empty string when {@code value} is {@code null}
1076	     */
1077	    private String normalizeForComparison(String value) {
1078	        if (value == null) {
1079	            return "";
1080	        }
1081	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
1082	    }
1083	}
