7	
8	/** email-blocklist: the disposable-domain blocklist is still applied first, so a
9	 * blocklisted email is rejected with 400 before identity checks. */
10	@Tag("cp38")
11	class Cp38Tests extends AcceptanceBase {
12	
13		@Test
