9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.nio.charset.StandardCharsets;
13	import java.security.MessageDigest;
14	import java.security.NoSuchAlgorithmException;
15	import java.time.LocalDate;
16	import java.time.Period;
17	import java.util.Collection;
18	import java.util.List;
19	import java.util.Locale;
20	
21	/**
22	 * Maps Owner & OwnerDto using Mapstruct
23	 */
24	@Mapper(uses = PetMapper.class)
25	public abstract class OwnerMapper {
26	
27	    /**
28	     * Points added when the owner has an email address.
29	     */
30	    private static final int EMAIL_POINTS = 2;
31	
32	    /**
33	     * Points added when the owner has no namesakes ({@code namesakeCount} is 0).
34	     */
35	    private static final int NO_NAMESAKE_POINTS = 1;
36	
37	    /**
38	     * Points added when the owner belongs to a household of {@value #LARGE_HOUSEHOLD_SIZE} or more members.
39	     */
40	    private static final int LARGE_HOUSEHOLD_POINTS = 2;
41	
42	    /**
43	     * The household size (members, including the owner) at which the large-household points are awarded.
44	     */
45	    private static final int LARGE_HOUSEHOLD_SIZE = 3;
46	
47	    /**
48	     * Points added when the owner's tenure reaches {@value #TENURE_POINTS_FISCAL_YEARS} elapsed fiscal year(s).
49	     */
50	    private static final int TENURE_POINTS = 3;
51	
52	    /**
53	     * Tenure, in elapsed fiscal years, that an owner must reach to earn the tenure points.
54	     */
55	    private static final int TENURE_POINTS_FISCAL_YEARS = 1;
56	
57	    /**
58	     * The month (1 July) on which the fiscal year starts.
59	     */
60	    private static final int FISCAL_YEAR_START_MONTH = 7;
61	
62	    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
63	    @Mapping(target = "initials", expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
64	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
65	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
66	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
67	    @Mapping(target = "membershipLevel", expression = "java(owner.getMembershipLevel() != null ? owner.getMembershipLevel() : membershipLevel(owner))")
68	    @Mapping(target = "locality", expression = "java(org.springframework.samples.petclinic.mapper.OwnerLocality.of(owner.getCity(), owner.getPostcode()))")
69	    @Mapping(target = "timezone", expression = "java(org.springframework.samples.petclinic.mapper.OwnerLocality.timezoneOf(owner.getCity(), owner.getPostcode()))")
70	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
71	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
72	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
73	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
74	    @Mapping(target = "selfLink", expression = "java(selfLink(owner))")
75	    @Mapping(target = "ownerSegment", expression = "java(ownerSegment(owner))")
76	    public abstract OwnerDto toOwnerDto(Owner owner);
77	
78	    public abstract Owner toOwner(OwnerDto ownerDto);
79	
80	    @Mapping(target = "id", ignore = true)
81	    @Mapping(target = "pets", ignore = true)
82	    public abstract Owner toOwner(OwnerFieldsDto ownerDto);
83	
84	    public abstract List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
85	
86	    public abstract Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
87	
88	    /**
89	     * Computes an owner's membership points. Points start at 0 and accumulate: {@value #EMAIL_POINTS} when an
90	     * email is present, {@value #NO_NAMESAKE_POINTS} when {@code namesakeCount} is 0,
91	     * {@value #LARGE_HOUSEHOLD_POINTS} for a household of {@value #LARGE_HOUSEHOLD_SIZE} or more members, and
92	     * {@value #TENURE_POINTS} for a tenure of at least {@value #TENURE_POINTS_FISCAL_YEARS} elapsed fiscal
93	     * year(s) (measured from {@code registrationDate}). Because a newly created owner has zero elapsed fiscal
94	     * years, a new owner never earns the tenure points.
95	     *
96	     * @param owner the owner whose points are being computed
97	     * @return the owner's membership points (0 or more)
98	     */
99	    protected Integer membershipPoints(Owner owner) {
100	        return membershipPoints(owner, owner.getHouseholdSize());
101	    }
102	
103	    /**
104	     * Computes an owner's membership points as {@link #membershipPoints(Owner)} does, but using the supplied
105	     * {@code householdSize} in place of the owner's stored one when awarding the large-household points. This
106	     * lets a caller evaluate an owner's points against the household's <em>current</em> size (for example when
107	     * computing the new-owner level ceiling) without mutating the owner.
108	     *
109	     * @param owner the owner whose points are being computed
110	     * @param householdSize the household size to measure the large-household points against
111	     * @return the owner's membership points (0 or more) for the given household size
112	     */
113	    protected Integer membershipPoints(Owner owner, Integer householdSize) {
114	        int points = 0;
115	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
116	            points += EMAIL_POINTS;
117	        }
118	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
119	            points += NO_NAMESAKE_POINTS;
120	        }
121	        if (householdSize != null && householdSize >= LARGE_HOUSEHOLD_SIZE) {
122	            points += LARGE_HOUSEHOLD_POINTS;
123	        }
124	        if (tenureFiscalYears(owner) >= TENURE_POINTS_FISCAL_YEARS) {
125	            points += TENURE_POINTS;
126	        }
127	        return points;
128	    }
129	
130	    /**
131	     * Maps an owner's membership points to a numeric membership level: level 1 for 0-1 points, level 2 for
132	     * 2-3 points, level 3 for 4-5 points, and level 4 for 6 or more points.
133	     *
134	     * @param owner the owner whose level is being computed
135	     * @return the membership level (between 1 and 4 inclusive)
136	     */
137	    protected Integer membershipLevel(Owner owner) {
138	        return levelForPoints(membershipPoints(owner));
139	    }
140	
141	    /**
142	     * Computes an owner's membership level as {@link #membershipLevel(Owner)} does, but measuring the
143	     * large-household points against the supplied {@code householdSize} rather than the owner's stored one.
144	     * This is the uncapped level an owner would report were the household of the given size; it is the value
145	     * the create endpoint compares between household members when computing a new owner's level ceiling.
146	     *
147	     * @param owner the owner whose level is being computed
148	     * @param householdSize the household size to measure the large-household points against
149	     * @return the membership level (between 1 and 4 inclusive) for the given household size
150	     */
151	    public Integer membershipLevelForHouseholdSize(Owner owner, Integer householdSize) {
152	        return levelForPoints(membershipPoints(owner, householdSize));
153	    }
154	
155	    /**
156	     * Maps membership points to a numeric membership level: level 1 for 0-1 points, level 2 for 2-3 points,
157	     * level 3 for 4-5 points, and level 4 for 6 or more points.
158	     *
159	     * @param points the membership points to map
160	     * @return the membership level (between 1 and 4 inclusive)
161	     */
162	    private Integer levelForPoints(int points) {
163	        if (points >= 6) {
164	            return 4;
165	        }
166	        if (points >= 4) {
167	            return 3;
168	        }
169	        if (points >= 2) {
170	            return 2;
171	        }
172	        return 1;
173	    }
174	
175	    /**
176	     * Computes an owner's tenure as the number of elapsed fiscal years between {@code registrationDate} and
177	     * today: the difference between the fiscal year (starting 1 July) of today and that of the registration
178	     * date. A newly created owner (registered in the current fiscal year) has zero tenure. Owners with no
179	     * {@code registrationDate}, or a registration date in a later fiscal year, are treated as zero tenure.
180	     *
181	     * @param owner the owner whose tenure is being computed
182	     * @return the owner's tenure in elapsed fiscal years, never negative
183	     */
184	    protected long tenureFiscalYears(Owner owner) {
185	        LocalDate registrationDate = owner.getRegistrationDate();
186	        if (registrationDate == null) {
187	            return 0;
188	        }
189	        long years = (long) fiscalYearStart(LocalDate.now()) - fiscalYearStart(registrationDate);
190	        return Math.max(years, 0);
191	    }
192	
193	    /**
194	     * Derives an owner's {@code fiscalYear}, formatted {@code 'FY<YY>'}, from the (already
195	     * business-day-adjusted) {@code registrationDate}. The fiscal year starts on 1 July and is labelled by
196	     * the calendar year in which it starts, so a registration on or after 1 July belongs to that year's
197	     * fiscal year and an earlier one to the previous year's (e.g. {@code 2026-08-15} yields {@code 'FY26'}).
198	     *
199	     * @param owner the owner whose fiscal year is being derived
200	     * @return the owner's fiscal year as {@code 'FY<YY>'}
201	     */
202	    protected String fiscalYear(Owner owner) {
203	        return "FY" + fiscalYearSuffix(owner.getRegistrationDate());
204	    }
205	
206	    /**
207	     * Returns the two-digit fiscal-year suffix ({@code '<YY>'}) for the given date: the last two digits of
208	     * the calendar year in which that date's fiscal year (starting 1 July) begins. This is the shared segment
209	     * used by both {@link #fiscalYear(Owner)} and the membership number.
210	     *
211	     * @param date the date whose fiscal-year suffix is computed
212	     * @return the zero-padded two-digit fiscal-year suffix
213	     */
214	    protected String fiscalYearSuffix(LocalDate date) {
215	        return String.format("%02d", fiscalYearStart(date) % 100);
216	    }
217	
218	    /**
219	     * Returns the calendar year in which the fiscal year containing {@code date} starts. The fiscal year
220	     * starts on 1 July, so dates from July onward start their fiscal year in the same calendar year, while
221	     * dates from January to June belong to the fiscal year that started in the previous calendar year.
222	     *
223	     * @param date the date whose fiscal-year start is computed
224	     * @return the calendar year in which the containing fiscal year starts
225	     */
226	    protected int fiscalYearStart(LocalDate date) {
227	        int year = date.getYear();
228	        return date.getMonthValue() >= FISCAL_YEAR_START_MONTH ? year : year - 1;
229	    }
230	
231	    /**
232	     * Derives an owner's preferred contact channel at read time: {@code 'EMAIL'} when an email address is
233	     * present, otherwise {@code 'PHONE'}.
234	     *
235	     * @param owner the owner whose contact preference is being computed
236	     * @return {@code 'EMAIL'} when the owner has a non-blank email, otherwise {@code 'PHONE'}
237	     */
238	    protected String contactPreference(Owner owner) {
239	        return (owner.getEmail() != null && !owner.getEmail().isBlank()) ? "EMAIL" : "PHONE";
240	    }
241	
242	    /**
243	     * Derives an owner's age band from {@code birthDate}, measured against {@code registrationDate}: the
244	     * completed years between the two dates place the owner in {@code 'MINOR'} (under 18), {@code 'ADULT'}
245	     * (18 to 64 inclusive) or {@code 'SENIOR'} (65 or over). Returns {@code null} when the owner has no
246	     * {@code birthDate}, so the field is simply absent for owners created without one.
247	     *
248	     * @param owner the owner whose age band is being derived
249	     * @return {@code 'MINOR'}, {@code 'ADULT'} or {@code 'SENIOR'}, or {@code null} when no birth date is set
250	     */
251	    protected String ageBand(Owner owner) {
252	        if (owner.getBirthDate() == null) {
253	            return null;
254	        }
255	        LocalDate reference = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
256	        int years = Period.between(owner.getBirthDate(), reference).getYears();
257	        if (years < 18) {
258	            return "MINOR";
259	        }
260	        if (years < 65) {
261	            return "ADULT";
262	        }
263	        return "SENIOR";
264	    }
265	
266	    /**
267	     * Derives an owner's {@code identityKey}: the lower-case hex SHA-256 digest of the normalized telephone,
268	     * the lower-cased email (or an empty string when absent) and the {@link #soundex(String) soundex} of the
269	     * last name, joined by {@code '|'} in that order before hashing. This is the single 64-hex key used for
270	     * duplicate detection, so the value returned here matches the one the create endpoint compares.
271	     *
272	     * @param owner the owner whose identity key is being derived
273	     * @return the owner's identity key, a 64-character lower-case hex SHA-256 digest
274	     */
275	    protected String identityKey(Owner owner) {
276	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
277	        String email = owner.getEmail() == null ? "" : owner.getEmail();
278	        String soundex = soundex(owner.getLastName());
279	        return sha256Hex(telephone + "|" + email + "|" + soundex);
280	    }
281	
282	    /**
283	     * Computes the full lower-case hex SHA-256 digest of the UTF-8 bytes of the given value.
284	     *
285	     * @param value the value to hash
286	     * @return the 64-character lower-case hex SHA-256 digest
287	     */
288	    private String sha256Hex(String value) {
289	        try {
290	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
291	            StringBuilder sb = new StringBuilder(digest.length * 2);
292	            for (byte b : digest) {
293	                sb.append(String.format("%02x", b));
294	            }
295	            return sb.toString();
296	        }
297	        catch (NoSuchAlgorithmException e) {
298	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
299	        }
300	    }
301	
302	    /**
303	     * Computes the American Soundex code of the given value: the retained (upper-cased) first letter
304	     * followed by three digits derived from the remaining consonants, right-padded with zeros or truncated
305	     * to length four. Non-letters are ignored; adjacent letters mapping to the same digit are coded once
306	     * (bridged across {@code 'H'}/{@code 'W'}), and vowels reset the run. A {@code null} or letter-free
307	     * value yields an empty string. This matches the create endpoint's soundex so identity keys agree.
308	     *
309	     * @param value the value (typically a last name) to encode
310	     * @return the four-character Soundex code, or an empty string when there are no letters
311	     */
312	    private String soundex(String value) {
313	        if (value == null) {
314	            return "";
315	        }
316	        String letters = value.toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
317	        if (letters.isEmpty()) {
318	            return "";
319	        }
320	        StringBuilder code = new StringBuilder().append(letters.charAt(0));
321	        char prev = soundexDigit(letters.charAt(0));
322	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
323	            char c = letters.charAt(i);
324	            if (c == 'H' || c == 'W') {
325	                continue;
326	            }
327	            char digit = soundexDigit(c);
328	            if (digit != '0' && digit != prev) {
329	                code.append(digit);
330	            }
331	            prev = digit;
332	        }
333	        while (code.length() < 4) {
334	            code.append('0');
335	        }
336	        return code.toString();
337	    }
338	
339	    private char soundexDigit(char c) {
340	        return switch (c) {
341	            case 'B', 'F', 'P', 'V' -> '1';
342	            case 'C', 'G', 'J', 'K', 'Q', 'S', 'X', 'Z' -> '2';
343	            case 'D', 'T' -> '3';
344	            case 'L' -> '4';
345	            case 'M', 'N' -> '5';
346	            case 'R' -> '6';
347	            default -> '0';
348	        };
349	    }
350	
351	    /**
352	     * Formats the owner's stored E.164 {@code telephone} for humans: the country code, a space, then the
353	     * national digits grouped in threes from the left (e.g. {@code '+61412345678'} becomes
354	     * {@code '+61 412 345 678'}). The raw {@code telephone} is left untouched in E.164 form. Values that are
355	     * {@code null} or not in E.164 form (no leading {@code '+'}) are returned unchanged.
356	     * <p>
357	     * The country code is split off using the codes the application recognises: {@code '+1'} (NANP) is a
358	     * single digit and any other number is assumed to carry the default {@code '+61'}-style two-digit code.
359	     *
360	     * @param owner the owner whose telephone is being formatted
361	     * @return the human-formatted telephone, or the raw value when it is {@code null} or not E.164
362	     */
363	    protected String telephoneDisplay(Owner owner) {
364	        String telephone = owner.getTelephone();
365	        if (telephone == null || !telephone.startsWith("+")) {
366	            return telephone;
367	        }
368	        String digits = telephone.substring(1);
369	        int countryCodeLength = digits.startsWith("1") ? 1 : 2;
370	        if (digits.length() <= countryCodeLength) {
371	            return telephone;
372	        }
373	        String countryCode = digits.substring(0, countryCodeLength);
374	        String national = digits.substring(countryCodeLength);
375	        StringBuilder grouped = new StringBuilder("+").append(countryCode);
376	        for (int i = 0; i < national.length(); i++) {
377	            if (i % 3 == 0) {
378	                grouped.append(' ');
379	            }
380	            grouped.append(national.charAt(i));
381	        }
382	        return grouped.toString();
383	    }
384	
385	    /**
386	     * Composes the owner's salutation: the {@code title}, a single space and the last name (e.g.
387	     * {@code 'DR Franklin'}) when a non-blank {@code title} was supplied, or just the last name when no
388	     * title was given.
389	     *
390	     * @param owner the owner whose salutation is being composed
391	     * @return {@code '<title> <lastName>'} when a title is present, otherwise the last name alone
392	     */
393	    protected String salutation(Owner owner) {
394	        String title = owner.getTitle();
395	        if (title == null || title.isBlank()) {
396	            return owner.getLastName();
397	        }
398	        return title + " " + owner.getLastName();
399	    }
400	
401	    /**
402	     * Derives an owner's {@code selfLink}: the canonical relative URL of the owner resource, formatted
403	     * {@code '/api/owners/<id>'} from the owner's id. Returns {@code null} when the owner has no id yet.
404	     *
405	     * @param owner the owner whose self link is being derived
406	     * @return the owner's self link, or {@code null} when the owner has no id
407	     */
408	    protected String selfLink(Owner owner) {
409	        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
410	    }
411	
412	    /**
413	     * Derives an owner's {@code ownerSegment}, formatted {@code '<TIER>_<AREA>'}. TIER is
414	     * {@code 'PREMIUM'} when the owner's effective membership level is 3 or more, otherwise
415	     * {@code 'STANDARD'}. AREA is {@code 'METRO'} when the owner's locality is a known region (NSW,
416	     * VIC or QLD), otherwise {@code 'REGIONAL'}. The result is one of {@code 'PREMIUM_METRO'},
417	     * {@code 'PREMIUM_REGIONAL'}, {@code 'STANDARD_METRO'} or {@code 'STANDARD_REGIONAL'}.
418	     *
419	     * @param owner the owner whose segment is being derived
420	     * @return the owner's segment as {@code '<TIER>_<AREA>'}
421	     */
422	    protected String ownerSegment(Owner owner) {
423	        Integer level = owner.getMembershipLevel() != null ? owner.getMembershipLevel() : membershipLevel(owner);
424	        String tier = level != null && level >= 3 ? "PREMIUM" : "STANDARD";
425	        String region = OwnerLocality.of(owner.getCity(), owner.getPostcode());
426	        boolean known = "NSW".equals(region) || "VIC".equals(region) || "QLD".equals(region);
427	        String area = known ? "METRO" : "REGIONAL";
428	        return tier + "_" + area;
429	    }
430	
431	    public OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
432	        OwnerPageDto ownerPageDto = new OwnerPageDto();
433	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
434	        ownerPageDto.setPage(ownerPage.getNumber());
435	        ownerPageDto.setSize(ownerPage.getSize());
436	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
437	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
438	        return ownerPageDto;
439	    }
440	}
